script:
(function () {
  'use strict';
  // 1031 like-kind exchange, following IRS Form 8824 Part III (2025 Instructions for Form 8824).
  // Cash is assumed to flow through the exchange: gross cash to you = (sale price - old mortgage)
  // - (purchase price - new mortgage) when positive, otherwise the shortfall is cash you pay.
  // Exchange expenses = selling costs + purchase closing costs.
  //   Line 15 = cash received + max(0, old mortgage - (new mortgage + cash paid)), reduced (not
  //             below 0) by exchange expenses.
  //   Line 18 = adjusted basis + expenses not used on line 15 + max(0, new mortgage + cash paid - old mortgage).
  //   Line 16 = FMV of like-kind property received (purchase price); 17 = 15 + 16; 19 = 17 - 18 (realized).
  //   Line 20 = min(line 15, line 19), not below 0 -> recognized gain (line 23 = 21 + 22 = line 20 total).
  //   Line 24 = line 19 - line 23 (deferred; a realized loss is all deferred, never recognized).
  //   Line 25 = line 18 + line 23 - line 15 (basis of the replacement property).
  // Verified (Node, scratchpad tests/g1031_lke.test.js) against the instructions' worked example:
  //   Taylor (FMV $220,000, basis $100,000, mortgage $80,000, gets $250,000 property with a $150,000
  //   mortgage + $40,000 cash): line 15 $40,000, 18 $170,000, 19 $120,000, 20 $40,000;
  //   Finley (the other side): line 15 $30,000, 18 $175,000, 19 $75,000, 20 $30,000.
  //   Defaults: realized $395,000 = sale - basis - all costs; recognized $45,000; basis $300,000 =
  //   replacement price - deferred gain. Loss case: realized -$50,000, recognized $0, deferred -$50,000.
  //   Blank or negative input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function exchange(sale, basis, sellCost, oldDebt, buy, buyCost, newDebt) {
    var expenses = sellCost + buyCost;
    var net = (sale - oldDebt) - (buy - newDebt);
    var cashIn = Math.max(0, net), cashOut = Math.max(0, -net);
    var debtRelief = Math.max(0, oldDebt - (newDebt + cashOut));
    var bootGross = cashIn + debtRelief;
    var expOn15 = Math.min(expenses, bootGross);
    var l15 = bootGross - expOn15;
    var l16 = buy;
    var l17 = l15 + l16;
    var l18 = basis + (expenses - expOn15) + Math.max(0, newDebt + cashOut - oldDebt);
    var l19 = l17 - l18;
    var l20 = Math.max(0, Math.min(l15, l19));
    var l23 = l20;
    var l24 = l19 - l23;
    var l25 = l18 + l23 - l15;
    return { expenses: expenses, cashIn: cashIn, cashOut: cashOut, debtRelief: debtRelief, expOn15: expOn15,
      l15: l15, l16: l16, l17: l17, l18: l18, l19: l19, l20: l20, l23: l23, l24: l24, l25: l25,
      netSale: sale - sellCost - oldDebt, netBuy: buy + buyCost - newDebt };
  }

  var IDS = ['lkeDeferred', 'lkeRecognized', 'lkeRealized', 'lkeNewBasis', 'lkeNote', 'lkeNetSale', 'lkeNetBuy', 'lkeCashLeft',
    'lkeCashBoot', 'lkeDebtBoot', 'lkeExpBoot', 'lkeBoot', 'lkeTaxNow', 'lkeTaxDeferred'];

  function update() {
    var sale = read('lkeSale'), basis = read('lkeBasis'), sellCost = read('lkeSellCost', true), oldDebt = read('lkeOldDebt', true),
        buy = read('lkeBuy'), buyCost = read('lkeBuyCost', true), newDebt = read('lkeNewDebt', true), taxRate = read('lkeTaxRate', true);
    var err = el('lkeError'), msg = '';
    if (isNaN(sale) || sale <= 0) msg = 'Enter the sale price of the property you are selling.';
    else if (isNaN(basis) || basis < 0) msg = 'Enter an adjusted basis of $0 or more.';
    else if (isNaN(buy) || buy <= 0) msg = 'Enter the purchase price of the replacement property.';
    else if ([sellCost, oldDebt, buyCost, newDebt].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Costs and mortgage amounts cannot be negative.';
    else if (isNaN(taxRate) || taxRate < 0 || taxRate > 60) msg = 'Enter a tax rate from 0% to 60%.';
    else if ([sale, basis, buy, sellCost, oldDebt, buyCost, newDebt].some(function (v) { return v > 1e12; })) msg = 'Amounts are too large.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); el('lkeLines').innerHTML = ''; return; }

    var r = exchange(sale, basis, sellCost, oldDebt, buy, buyCost, newDebt);
    var t = taxRate / 100;
    setText('lkeDeferred', signed(r.l24));
    setText('lkeRecognized', money.format(r.l23));
    setText('lkeRealized', signed(r.l19));
    setText('lkeNewBasis', money.format(r.l25));
    setText('lkeNetSale', signed(r.netSale));
    setText('lkeNetBuy', signed(r.netBuy));
    var left = r.netSale - r.netBuy;
    setText('lkeCashLabel', left >= 0 ? 'Cash left over for you' : 'Extra cash you add');
    setText('lkeCashLeft', money.format(Math.abs(left)));
    setText('lkeCashBoot', money.format(r.cashIn));
    setText('lkeDebtBoot', money.format(r.debtRelief));
    setText('lkeExpBoot', r.expOn15 > 0 ? '−' + money.format(r.expOn15) : money.format(0));
    setText('lkeBoot', money.format(r.l15));
    setText('lkeTaxNow', money.format(r.l23 * t));
    setText('lkeTaxDeferred', money.format(Math.max(0, r.l24) * t));

    var note;
    if (r.l19 <= 0) note = 'The exchange realizes a loss. A loss on like-kind property cannot be deducted in a 1031 exchange; it carries into the replacement property through its basis instead.';
    else if (r.l23 <= 0) note = 'All of the gain is deferred: the cash and debt relief you receive are fully offset by your exchange costs, the debt you take on or the cash you add.';
    else {
      var parts = [];
      if (r.cashIn > 0) parts.push(money.format(r.cashIn) + ' of sale proceeds not reinvested (before costs)');
      if (r.debtRelief > 0) parts.push(money.format(r.debtRelief) + ' of mortgage relief not matched by new debt or added cash');
      note = 'You receive ' + money.format(r.l15) + ' of taxable boot, so that much of the gain is taxed now. It comes from ' + parts.join(' and ') +
        (r.expOn15 > 0 ? ', less ' + money.format(r.expOn15) + ' of exchange costs' : '') +
        '. Buying a replacement at least as valuable and reinvesting all of your net cash avoids boot.';
    }
    setText('lkeNote', note);

    var lines = [
      ['15', 'Cash and net debt relief received, less exchange costs', money.format(r.l15)],
      ['16', 'Fair market value of the like-kind property received', money.format(r.l16)],
      ['17', 'Line 15 plus line 16', money.format(r.l17)],
      ['18', 'Adjusted basis, remaining exchange costs and net debt or cash you added', money.format(r.l18)],
      ['19', 'Gain or (loss) realized', signed(r.l19)],
      ['20', 'Smaller of line 15 or line 19, not below zero', money.format(r.l20)],
      ['23', 'Recognized gain', money.format(r.l23)],
      ['24', 'Deferred gain or (loss)', signed(r.l24)],
      ['25', 'Basis of like-kind property received', money.format(r.l25)]
    ];
    el('lkeLines').innerHTML = lines.map(function (l) {
      return '<tr><td>' + l[0] + '</td><td>' + l[1] + '</td><td>' + l[2] + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lkeForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
